     9	const PREFIX_TO_PACK = {
    10	  Fa6: 'fa6', Fa: 'fa', Md: 'md', Hi2: 'hi2', Hi: 'hi',
    11	  Lu: 'lu', Bi: 'bi', Io5: 'io5', Io: 'io', Ri: 'ri',
    12	  Tb: 'tb', Gi: 'gi', Wi: 'wi', Bs: 'bs', Pi: 'pi',
    13	  Go: 'go', Fi: 'fi', Ai: 'ai', Cg: 'cg', Sl: 'sl',
    14	  Lia: 'lia', Rx: 'rx', Vsc: 'vsc', Si: 'si',
    15	};
