    17	function packFor(name) {
    18	  const keys = Object.keys(PREFIX_TO_PACK).sort((a, b) => b.length - a.length);
    19	  for (const p of keys) {
    20	    if (name.startsWith(p) && name.length > p.length) return PREFIX_TO_PACK[p];
    21	  }
    22	  return 'fa';
    23	}
    24	
    25	function loadIcon(name) {
    26	  const pack = packFor(name);
    27	  let mod;
    28	  try {
    29	    mod = require(`react-icons/${pack}`);
    30	  } catch (err) {
    31	    throw new Error(`react-icons/${pack} is not available (icon ${name}): ${err.message}`);
    32	  }
    33	  const Icon = mod[name];
    34	  if (!Icon) {
    35	    throw new Error(`icon ${name} not found in react-icons/${pack}`);
    36	  }
    37	  return Icon;
    38	}
